def get_xapi_experience_api_catalog() -> List[XapiExperienceApiRecord]:
    """Return complete xapi_experience_api registry."""
    return REGISTRY_XAPI_EXPERIENCE_API


def query_xapi_experience_api_by_difficulty(difficulty_level: str) -> List[XapiExperienceApiRecord]:
    """Filter xapi_experience_api elements matching difficulty."""
    return [item for item in REGISTRY_XAPI_EXPERIENCE_API if item.difficulty == difficulty_level]


def calculate_xapi_experience_api_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_XAPI_EXPERIENCE_API)

